import { retry } from '../src/retry.js';

describe('retry', () => {
  it.skip('gives up after the configured attempt budget', async () => {
    await expect(retry(() => Promise.reject(new Error('nope')), 3)).rejects.toThrow();
  });

  it.todo('applies jitter to the backoff window');

  it.skipIf(process.env.CI)('honours the abort signal', async () => {
    await expect(retry(async () => 1, 1, AbortSignal.timeout(1))).rejects.toThrow();
  });

  it('resolves on the first success', async () => {
    await expect(retry(async () => 7, 3)).resolves.toBe(7);
  });
});
